// Coach outcomes (Phase 7.2) — did the advice work?
//
// Pure functions: advice docs + workout history in, factual outcome lines out.
// The coach's context gets these so it can reference its own track record —
// numbers only, no causal claims (the prompt already forbids overclaiming).
// No Firebase, no DOM — fully unit-testable.
//
// MIRRORED: functions/coach-outcomes.js is generated by
//   node scripts/sync-mirror.mjs js/core/features/coach-outcomes.js functions/coach-outcomes.js
// (tests/unit/movement-patterns-mirror.test.js enforces parity).

const DAY_MS = 86400000;

function toDate(s) {
    return new Date(`${s}T12:00:00`);
}

function daysBetween(a, b) {
    return Math.round((toDate(b) - toDate(a)) / DAY_MS);
}

/**
 * Weight in `toUnit`, 1 decimal (AP-15c). Unlike ui-helpers#convertWeight
 * there is no >1000 corruption cap — this also converts volumes. Exported:
 * the functions/ mirror is the server's one unit converter (coach tools,
 * weekly review), so client and server round identically.
 */
export function convertToUnit(weight, fromUnit, toUnit) {
    const w = Number(weight);
    if (!Number.isFinite(w) || w === 0) return 0;
    const from = fromUnit === 'kg' ? 'kg' : 'lbs';
    const to = toUnit === 'kg' ? 'kg' : 'lbs';
    let out = w;
    if (from === 'lbs' && to === 'kg') out = w * 0.453592;
    else if (from === 'kg' && to === 'lbs') out = w * 2.20462;
    return Math.round(out * 10) / 10;
}

/**
 * Max completed working-set weight for an exercise in a date window, in
 * `unit` — a kg session must not compare raw against a lbs target.
 */
function maxWeightIn(workouts, exercise, from, to, unit = 'lbs') {
    const target = exercise.toLowerCase();
    let max = 0;
    for (const w of workouts) {
        if (!w.date || w.date < from || w.date > to || !w.completedAt) continue;
        const names = w.exerciseNames || {};
        for (const [key, ex] of Object.entries(w.exercises || {})) {
            const name = (names[key] || ex.name || '').toLowerCase();
            if (name !== target) continue;
            for (const s of (ex.sets || [])) {
                if (s.weight && s.type !== 'warmup' && s.completed !== false) {
                    max = Math.max(max, convertToUnit(s.weight, s.originalUnit || 'lbs', unit));
                }
            }
        }
    }
    return max;
}

/** Total completed sets across all exercises in a date window. */
function totalSetsIn(workouts, from, to) {
    let sets = 0;
    for (const w of workouts) {
        if (!w.date || w.date < from || w.date > to || !w.completedAt) continue;
        for (const ex of Object.values(w.exercises || {})) {
            sets += (ex.sets || []).filter(s => s.completed !== false && (s.reps || s.weight)).length;
        }
    }
    return sets;
}

/** Was the exercise done at all in a date window? */
function exerciseDoneIn(workouts, exercise, from, to) {
    const target = exercise.toLowerCase();
    return workouts.some(w => {
        if (!w.date || w.date < from || w.date > to || !w.completedAt) return false;
        const names = w.exerciseNames || {};
        return Object.entries(w.exercises || {}).some(([key, ex]) =>
            (names[key] || ex.name || '').toLowerCase() === target && (ex.sets || []).length > 0);
    });
}

function shiftDate(dateStr, days) {
    const d = toDate(dateStr);
    d.setDate(d.getDate() + days);
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

/**
 * Compute one advice doc's outcome line, or null when it's not yet checkable
 * (too fresh, too old to matter, or a type with nothing to measure).
 *
 * @param {object} advice - {date, exercise, type, detail, targetValue, unit?}
 * @param {Array} workouts - full workout history (any order)
 * @param {string} today - YYYY-MM-DD
 * @param {{unit?: string}} [opts] - display unit; weights are compared in the
 *   advice's own stamped unit when present (the unit it was prescribed in),
 *   else in this one
 */
export function computeAdviceOutcome(advice, workouts, today, { unit = 'lbs' } = {}) {
    if (!advice?.date || !advice.type) return null;
    const age = daysBetween(advice.date, today);
    // Under 2 weeks: not enough follow-up data. Over ~10 weeks: stale.
    if (age < 14 || age > 70) return null;

    const before4w = shiftDate(advice.date, -28);
    const after4wEnd = shiftDate(advice.date, 28);
    const when = advice.date;
    const u = advice.unit === 'kg' || advice.unit === 'lbs' ? advice.unit : (unit === 'kg' ? 'kg' : 'lbs');

    switch (advice.type) {
        case 'weight_target': {
            if (!advice.exercise || !advice.targetValue) return null;
            const bestAfter = maxWeightIn(workouts, advice.exercise, when, today, u);
            const bestBefore = maxWeightIn(workouts, advice.exercise, before4w, when, u);
            if (!bestAfter && !bestBefore) return null;
            const hit = bestAfter >= advice.targetValue;
            return `${when} — suggested ${advice.exercise} target ${advice.targetValue} ${u}; ${hit ? `hit (best since: ${bestAfter})` : `not hit yet (best since: ${bestAfter || 'none'})`}; was ${bestBefore || 'n/a'} in the 4 weeks before.`;
        }
        case 'deload': {
            const weekBefore = totalSetsIn(workouts, shiftDate(when, -7), when);
            const weekAfter = totalSetsIn(workouts, when, shiftDate(when, 7));
            if (!weekBefore) return null;
            const pct = Math.round(((weekAfter - weekBefore) / weekBefore) * 100);
            let liftLine = '';
            if (advice.exercise) {
                const before = maxWeightIn(workouts, advice.exercise, before4w, when, u);
                const after = maxWeightIn(workouts, advice.exercise, when, after4wEnd, u);
                if (before && after) liftLine = `; ${advice.exercise} ${before}→${after} ${u} in the 4 weeks after`;
            }
            return `${when} — suggested a lighter week${advice.exercise ? ` for ${advice.exercise}` : ''}; volume ${pct >= 0 ? '+' : ''}${pct}% that week${liftLine}.`;
        }
        case 'exercise_swap': {
            const swapTo = advice.targetValue || advice.detail;
            if (!swapTo || typeof swapTo !== 'string') return null;
            const stillDoing = exerciseDoneIn(workouts, swapTo, shiftDate(today, -14), today);
            const everDid = exerciseDoneIn(workouts, swapTo, when, today);
            if (!everDid) return `${when} — suggested swapping to ${swapTo}; never tried it.`;
            return `${when} — suggested swapping to ${swapTo}; ${stillDoing ? 'still doing it' : 'tried it but dropped it'}.`;
        }
        case 'volume_change': {
            const weekBefore = totalSetsIn(workouts, shiftDate(when, -7), when);
            const weekAfter = totalSetsIn(workouts, when, shiftDate(when, 7));
            if (!weekBefore || !weekAfter) return null;
            const pct = Math.round(((weekAfter - weekBefore) / weekBefore) * 100);
            return `${when} — suggested volume change (${advice.detail || 'unspecified'}); weekly sets ${pct >= 0 ? '+' : ''}${pct}% the following week.`;
        }
        default:
            // 'technique' and unknown types aren't numerically checkable.
            return null;
    }
}

/**
 * The `Your past recommendations and what happened:` context block.
 * @returns {string} '' when nothing checkable yet.
 */
export function buildOutcomesContext(adviceDocs = [], workouts = [], today, { limit = 10, unit = 'lbs' } = {}) {
    const lines = (adviceDocs || [])
        .slice()
        .sort((a, b) => (b.date || '').localeCompare(a.date || ''))
        .map(a => computeAdviceOutcome(a, workouts, today, { unit }))
        .filter(Boolean)
        .slice(0, limit);
    if (!lines.length) return '';
    return `Your past recommendations and what happened (correlation, not causation):\n${lines.join('\n')}\n`;
}

/**
 * Style feedback line (7.3): "user thumbed down 2 of your last 10 answers".
 * @param {Array<'up'|'down'>} recentFeedback - newest first
 */
export function buildFeedbackContext(recentFeedback = []) {
    const rated = recentFeedback.filter(f => f === 'up' || f === 'down');
    if (!rated.length) return '';
    const downs = rated.filter(f => f === 'down').length;
    if (downs === 0) return '';
    return `Feedback: the user thumbed down ${downs} of your last ${rated.length} rated answers — tighten up what didn't land (usually long or generic).\n`;
}
